 function chooseStudioTemplate(id:string){setStudioTemplate(id);sessionStorage.setItem(`qpg-studio-template:${subject.id}`,id);}
 const [syllabuses,setSyllabuses]=useState<Syllabus[]>([]);const [blueprints,setBlueprints]=useState<Blueprint[]>([]);const [papers,setPapers]=useState<PaperSummary[]>([]);
 const [syllabus,setSyllabus]=useState('');const [blueprint,setBlueprint]=useState('');const [paper,setPaper]=useState<Paper|null>(null);const [title,setTitle]=useState('');const [slot,setSlot]=useState<Item|null>(null);
 const [examinationSession,setExaminationSession]=useState('');const [instructions,setInstructions]=useState('');const [comment,setComment]=useState('');const [history,setHistory]=useState<History[]>([]);const [historical,setHistorical]=useState(false);
