 function isReady(item:Item){return !!item.snapshot||!!aiBuild?.positions.find(p=>p.item_id===item.id)?.job?.results.some(r=>r.decision==='ACCEPTED'&&r.review_status==='APPROVED');}
 function duplicateComparison(item:Item){
  const candidate=aiBuild?.positions.find(p=>p.item_id===item.id)?.job?.results.find(r=>r.decision!=='REJECTED');
  if(!candidate)return null;
  const normalize=(text:string)=>text.trim().toLowerCase().replace(/\s+/g,' ');
  const match=aiBuild?.positions.find(p=>p.item_id!==item.id&&p.job?.results.some(r=>r.decision==='ACCEPTED'&&normalize(r.question.question_text)===normalize(candidate.question.question_text)));
  const other=match?.job?.results.find(r=>r.decision==='ACCEPTED');
  return match&&other?{text:candidate.question.question_text,other:other.question.question_text,label:match.label}:null;
 }
 function issueReason(item:Item){
  const position=aiBuild?.positions.find(p=>p.item_id===item.id);
  const candidate=position?.job?.results.find(r=>r.decision!=='REJECTED');
  const text=candidate?.question.question_text.trim().toLowerCase().replace(/\s+/g,' ');
  const matching=aiBuild?.positions.find(p=>p.item_id!==item.id&&p.job?.results.some(r=>r.decision==='ACCEPTED'&&r.question.question_text.trim().toLowerCase().replace(/\s+/g,' ')===text));
  if(candidate?.duplicate||matching)return matching?`Same wording as Q${matching.label}. Edit or replace this question.`:'Saved wording found. Add the ready set to reuse a compatible bank question; incompatible matches will show a specific reason.';
  if(position?.job?.failure_reason)return position.job.failure_reason;
  if(position?.job?.status==='RUNNING'||position?.job?.status==='QUEUED')return 'Question generation is in progress.';
  if(candidate)return 'Candidate needs saving or correction before it can be added.';
  return 'No question selected. Add one manually or choose from the Question Bank.';
 }
 const issueItems=paper?.items.filter(item=>!isReady(item))||[];
