 function focusQuestion(number:string){if(!paper)return;const item=paper.items.find(i=>positionName(i).replace(/[^a-z0-9]/gi,'').toLowerCase()===number.replace(/[^a-z0-9]/gi,'').toLowerCase()||String(i.position)===number);if(!item)return;setEditorTab('questions');if(!item.snapshot&&aiBuild&&!aiBuild.stale&&['COMPLETED','FAILED'].includes(aiBuild.status)&&aiBuild.positions.some(p=>p.item_id===item.id&&p.job?.results.some(r=>['PENDING','ACCEPTED'].includes(r.decision)))){const tools=document.getElementById(`qpg-ai-tools-${paper.id}`) as HTMLDetailsElement|null;if(tools)tools.open=true;setAiEditRequest(previous=>({itemId:item.id,sequence:(previous?.sequence||0)+1}));return;}setFocusedPosition(item.id);requestAnimationFrame(()=>{const target=document.getElementById(`qpg-position-${item.id}`);const parent=target?.closest('details');if(parent)parent.open=true;target?.scrollIntoView({behavior:'smooth',block:'center'});target?.focus({preventScroll:true});});}
 function showDetails(){setEditorTab('details');requestAnimationFrame(()=>{if(detailsRef.current){detailsRef.current.open=true;detailsRef.current.querySelector<HTMLInputElement>('input[aria-label="Paper title"]')?.focus({preventScroll:true});}});}
 const mappingSection=paper?.blueprint_snapshot.sections.find(section=>section.id===bankSection)||paper?.blueprint_snapshot.sections.find(section=>paper.items.some(item=>item.section_id===section.id&&!item.snapshot))||paper?.blueprint_snapshot.sections[0];
 const mappingItems=paper?.items.filter(item=>item.section_id===mappingSection?.id)||[];
