 useEffect(()=>{if(!paper||!editable)return;const changed=title!==paper.title||instructions!==(paper.metadata?.instructions||'')||examinationSession!==(paper.metadata?.examination_session||'')||!sameDocumentSettings(documentDetails,paper.metadata?.document_details)||!sameDocumentSettings(documentStyle,paper.metadata?.document_style);const key=`qpg-paper-edits:${paper.id}`;if(changed)sessionStorage.setItem(key,JSON.stringify({revision:paper.revision,title,instructions,examinationSession,documentDetails,documentStyle}));else sessionStorage.removeItem(key);const warn=(event:BeforeUnloadEvent)=>{if(changed){event.preventDefault();event.returnValue='';}};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn);},[paper,editable,title,instructions,examinationSession,documentDetails,documentStyle]);

