 async function run(work:()=>Promise<void>){setBusy(true);setError('');try{await work();}catch(e){const response=(e as {response?:{data?:unknown}}).response;if(response?.data instanceof Blob){try{response.data=JSON.parse(await response.data.text());}catch{/* Keep the existing generic error message for non-JSON responses. */}}const d=(e as {response?:{data?:{detail?:{message?:string;errors?:string[]}}}}).response?.data?.detail;setError(d?.errors?`${d.message} ${d.errors.join(' ')}`:collegeError(e));}finally{setBusy(false);}}
 async function save(){if(!paper)return null;if(title===paper.title&&instructions===(paper.metadata?.instructions||'')&&examinationSession===(paper.metadata?.examination_session||'')&&sameDocumentSettings(documentDetails,paper.metadata?.document_details)&&sameDocumentSettings(documentStyle,paper.metadata?.document_style)){setSaveNotice('Your draft is already saved.');return paper;}const next=await qpgApi.save<Paper>(`papers/${paper.id}`,{title,instructions,examination_session:examinationSession,document_details:documentDetails,document_style:documentStyle,expected_revision:paper.revision},true);await received(next);setSaveNotice('Paper details saved. Continue editing questions or preview your draft.');return next;}
